import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"狭缝与扫描平均","description":"","frontmatter":{"title":"狭缝与扫描平均","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/slit-scan-average.md","filePath":"litho/slit-scan-average.md","lastUpdated":1789023840000}'),m={name:"litho/slit-scan-average.md"};function E(c,a,A,_,B,u){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="狭缝与扫描平均" tabindex="-1">狭缝与扫描平均 <a class="header-anchor" href="#狭缝与扫描平均" aria-label="Permalink to &quot;狭缝与扫描平均&quot;">​</a></h1><div class="epigraph"><p>扫描方向上，晶圆每一点看见的是狭缝里那一段镜头与剂量的时间平均；垂直狭缝的方向没有这场平均，指纹会留下。</p><footer>—— 据 ASML 对 step-and-scan 狭缝照明与扫描积分的公开描述整理</footer></div><p><a href="/litho/stepper-vs-scanner">上一课</a>钉死了步进器整场一闪、扫描机狭缝同步扫。缺口是那场运动学里已经点到、却还没写成算子的那一句：沿扫描方向，像差与剂量被积分；沿狭缝方向，瞬时视场仍是静态的。本课写这个平均。<a href="/litho/dose-control">剂量闭环</a>怎样把积分值锁到 \\(\\mathrm{mJ/cm^2}\\)，留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>扫描机的瞬时照明是一条与扫描方向垂直的狭缝。掩模与晶圆按缩比同步走，狭缝扫过整场。上一课说「镜头只需在狭缝里做到均匀」。缺口是：均匀是对谁而言——是狭缝里每个 \\(x\\) 当场合格，还是扫完之后每个晶圆点只关心积分？</p><p>沿扫描方向（常记为 \\(y\\)），每个曝光点依次穿过狭缝的前缘到后缘，收到的剂量是狭缝剖面 \\(I_\\mathrm{slit}(y&#39;)\\) 的积分，收到的有效像差是这段路径上镜头指纹的加权平均。沿狭缝方向（\\(x\\)）没有这场时间平均：照明不均匀、像散随 \\(x\\) 变，会直接印成场内 CD 与套刻指纹。把扫描机理解成「整场镜头突然变好了」，会漏掉各向异性。</p><h3 id="平均不是免费消像差" tabindex="-1">平均不是免费消像差 <a class="header-anchor" href="#平均不是免费消像差" aria-label="Permalink to &quot;平均不是免费消像差&quot;">​</a></h3><p>扫描平均能压掉沿 \\(y\\) 快速变化的分量，压不掉沿狭缝几乎不变的场曲、像散，也压不掉与扫描同步误差耦合的动态项。同步一抖，平均核被加了一个位置噪声，套刻预算里的扫描机项就会抬头——上一课运动学已经警告过，本课只把它读成「平均核被扰动」。</p><p><span class="marginnote">ASML 浸没公开场常见 \\(26\\,\\mathrm{mm}\\)（狭缝方向）\\(\\times 33\\,\\mathrm{mm}\\)（扫描拼出）。\\(26\\,\\mathrm{mm}\\) 受瞬时像场限制，不能靠「再扫一会儿」变宽。不要把两个轴的规格写成同一个镜头直径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把狭缝剖面写成扫描方向上的权重。晶圆点的剂量</p> \\[E \\propto v^{-1}\\int I_\\mathrm{slit}(y&#39;)\\,\\mathrm{d}y&#39;, \\]<p>\\(v\\) 是扫描速度。像差有效值是同一权重对狭缝内 Zernike（或波像差）的积分。产线表征因此拆成两张图：across-slit（\\(x\\)）均匀性与像差指纹；along-scan 则查速度稳定性与狭缝剖面是否对称。</p><p>步进器没有这条积分，全场静态图就是曝光图。扫描机的「场内 CD 更匀」主要来自 \\(y\\) 向平均，不是因为玻璃突然没有像差。比较两台机器的镜头指纹，必须声明是静态狭缝图还是扫描后的有效图。</p><h3 id="与照明光瞳的关系" tabindex="-1">与照明光瞳的关系 <a class="header-anchor" href="#与照明光瞳的关系" aria-label="Permalink to &quot;与照明光瞳的关系&quot;">​</a></h3><p>光瞳（\\(\\sigma\\)、环形、偶极）在曝光过程中仍由照明决定，并不被扫描「平均成圆瞳」。扫的是物面狭缝，不是把光瞳转一圈。偶极沿 \\(x\\) 或沿 \\(y\\) 时，场内指纹与扫描轴的相对取向会变，OPE 曲线也会变，但机制不在本课重讲邻近。</p>',16)),(e(),n(d,null,{default:r(()=>[h(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SLIT%5B%22%E7%8B%AD%E7%BC%9D%E7%9E%AC%E6%97%B6%E8%A7%86%E5%9C%BA%22%5D%20--%3E%20X%5B%22%E6%B2%BF%E7%8B%AD%E7%BC%9D%3A%20%E9%9D%99%E6%80%81%E6%8C%87%E7%BA%B9%22%5D%0A%20%20SLIT%20--%3E%20Y%5B%22%E6%B2%BF%E6%89%AB%E6%8F%8F%3A%20%E6%97%B6%E9%97%B4%E5%B9%B3%E5%9D%87%22%5D%0A%20%20Y%20--%3E%20DOSE%5B%22%E7%A7%AF%E5%88%86%E5%89%82%E9%87%8F%22%5D%0A%20%20Y%20--%3E%20ABR%5B%22%E6%9C%89%E6%95%88%E5%83%8F%E5%B7%AE%22%5D%0A%20%20V%5B%22%E6%89%AB%E6%8F%8F%E9%80%9F%E5%BA%A6%22%5D%20--%3E%20DOSE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>准分子脉冲在扫描方向上被一串脉冲铺成连续剂量。狭缝宽度、脉冲频率与 \\(v\\) 共同决定每个点吃到多少个脉冲。\\(N\\) 太少，脉间涨落会印成沿扫描的剂量纹；下一课的闭环正是为这场积分服务的。剖面中间亮、两头收，是为了边缘连续；若剖面歪，平均焦点与平均像散会偏，表现为沿扫描的 CD 斜率。镜头沿 \\(y\\) 的热漂移若慢于一场扫描，会被这场平均吃掉一部分；沿 \\(x\\) 的热则整场留下。偶极照明若把能量集中在瞳的左右，狭缝两端的有效像差可以差一截——平均核的权重不再均匀，CD 指纹会跟照明模式走。</p><p>动态同步误差（掩模台与晶圆台相对）让狭缝里的物点对不准像点，等效在平均时混入横向抖动与离焦。这是步进器没有的通道，也是套刻预算里扫描机项的来源之一。</p><p><span class="marginnote">浸没喷淋头跟着狭缝走，流体的「狭缝」与光学狭缝要对齐。那是浸没课的流体缺口。本课的平均算子在干式与浸没上形式相同，只是介质不同。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 EUV 真空扫描的磁浮细节搬进来，也不讨论狭缝宽度的具体毫米数作为万能规格——随机型与照明模式变。剂量如何用能量传感器闭环，是下一课；本课只给出 \\(E\\) 与 \\(v\\)、狭缝剖面的关系。胶灵敏度会倒逼 \\(v\\)，化学在抗蚀剂课写，这里不展开 PAG。</p><p>不要把「扫描平均」写成可以替代镜头装配。\\(x\\) 向不合格，扫得再稳也留在场上。照明模式一换，狭缝两端的有效像差权重会变，平均核不是与光瞳无关的几何常数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>扫描方向对剂量与像差做加权时间平均；狭缝方向留下静态指纹。</li><li>剂量 \\(\\propto\\) 狭缝积分 / 扫描速度。</li><li>同步抖动扰动平均核，进入套刻与有效焦深。</li><li>场的两个边长物理意义不同，不可都当成镜头一次成像的圆。</li><li>出处：ASML 对扫描投影、狭缝照明与 TWINSCAN 的公开说明；Levinson 对 step-and-scan 的讨论。</li></ul>',9))])}const x=o(m,[["render",E]]);export{D as __pageData,x as default};
